  import org.apache.log4j.Logger;

  import sailpoint.object.Application;
  import sailpoint.object.Custom;
  import sailpoint.object.Identity;
  import sailpoint.object.Link;
  import sailpoint.object.ProvisioningPlan;
  import sailpoint.object.ProvisioningPlan.AccountRequest;
  import sailpoint.object.ProvisioningPlan.AttributeRequest;
  import sailpoint.object.Workflow;

  import sailpoint.api.IdentityService;
  import sailpoint.api.SailPointContext;

  Logger log = Logger.getLogger("iiq.alpha.Alpha-Workflow-Mover-Rule-Library");



  public ProvisioningPlan getMoverPlan(Workflow workflow,String identityName,String oldDepartment,String newDepartment)
  {
    log.debug("Entered Alpha-Workflow-Mover-Rule-Library getMoverPlan method ");

    ProvisioningPlan plan = workflow.get("plan");
    if(plan == null)
    {
      plan = new ProvisioningPlan();
    }

    Identity identity = context.getObjectByName(Identity.class, identityName);		
    IdentityService idService = new IdentityService(context);

    //Build mover plan for AD application
    String AD_appName = "Alpha - Active Directory";
    Application ADappObj = context.getObjectByName(Application.class,AD_appName);

    List AD_links = idService.getLinks(identity, ADappObj);

    //Get department corresponding AD OU from custom object
    Custom OU_customObj = context.getObject(Custom.class,"Alpha-Custom-Joiner OU Mappings");
    if(null!=OU_customObj)
    {
      Map deptMap = OU_customObj.get("Department");
    }

    //Loop through AD links and calculate new DN based on new department
    if(!AD_links.isEmpty())
    {
      for(Link link : AD_links)
      {
        String old_DN = (String) link.getAttribute("distinguishedName");
        String new_DN = "";

        String nativeId = link.getNativeIdentity();

        log.debug("Old DN : "+old_DN);

        if(null != deptMap.get(oldDepartment))
        {
          String oldDepartmentOU = "OU="+deptMap.get(oldDepartment);

          if(old_DN.contains(oldDepartmentOU))
          {
            if(null != deptMap.get(newDepartment))
            {
              String newdepartmentOU = "OU="+deptMap.get(newDepartment);
              new_DN = old_DN.replace(oldDepartmentOU,newdepartmentOU);
              log.debug("New DN : "+new_DN);

              AccountRequest acctReq = new AccountRequest(AccountRequest.Operation.Modify, AD_appName, null, nativeId);
              acctReq.add(new AttributeRequest("AC_NewParent",new_DN));

              plan.add(acctReq);
            }
          }
        }
      }

      plan.setIdentity(identity);
      log.debug("Provisioning Plan : " +  plan.toXml());
    }

    return plan;

  }
